from taf.ul.ettf.utils.robot_handlers import with_callback_name

TEMP_SUFFIX = '_temp'

logger = custom_logger('TsharkCapturer')
logger_throughput = custom_logger('ThroughputTsharkCapturer')


def log_process(logger, process):
    logger.debug('Tshark process started. command {}'.format(' '.join(process.cmd)))


def apply_filter(output_filepath, wireshark_filter):
    temp_filepath = output_filepath + TEMP_SUFFIX
    os.rename(output_filepath, temp_filepath)
    filtering_process = Tshark()
    filtering_process.set_filter(wireshark_filter)
    filtering_process.set_input_file(temp_filepath)
    filtering_process.set_output_file(output_filepath)
    filtering_process.run_until_completion()
    log_process(logger, filtering_process)
    os.remove(temp_filepath)


class TsharkCapturer(Collector):
    CAPTURING_STARTED_TIMEOUT = 8.0
    FILE_EXTENSION = '.pcap'

    def __init__(self, logs_path, filename, interfaces, capturing_filter=None, post_processing_filter=None):
        self.capturing_process = Tshark()
        self.capturing_filter = capturing_filter
        self.post_processing_filter = post_processing_filter
        self.output_filepath = os.path.join(logs_path, filename) + self.FILE_EXTENSION
        self._assert_interfaces(interfaces)
        self.interfaces = interfaces

    def _assert_interfaces(self, interfaces):
        assert isinstance(interfaces, list), 'interfaces should be a list of names (string) of interfaces'

        for interface in interfaces:
            assert isinstance(interface, str), 'every interface name should be a string'

    def start(self):
        for interface in self.interfaces:
            self.capturing_process.set_interface(interface)
        if self.capturing_filter:
            self.capturing_process.set_capture_filter(self.capturing_filter)

        self.capturing_process.set_output_file(self.output_filepath)
        log_process(logger, self.capturing_process)
        self.capturing_process.start()
        self.capturing_process.wait_for_capturing_started(self.CAPTURING_STARTED_TIMEOUT)

    @with_callback_name('Stop Tshark Capturer')
    def stop(self):
        self.capturing_process.stop()
        if self.post_processing_filter:
            apply_filter(self.output_filepath, self.post_processing_filter)

    def __enter__(self):
        self.start()
        return self

    def __exit__(self, *args, **kwargs):
        self.stop()


class ThroughputTsharkCapturer(TsharkCapturer):

    def __init__(self, logs_path, filename, interfaces, capturing_snaplen=None):
        super(ThroughputTsharkCapturer, self).__init__(logs_path, filename, interfaces)
        self.capturing_snaplen = capturing_snaplen

    def start(self):
        self.capturing_process = Tshark()
        for interface in self.interfaces:
            self.capturing_process.set_interface(interface)
        if self.capturing_snaplen:
            self.capturing_process.set_capture_snaplen(self.capturing_snaplen)

        self.capturing_process.set_output_file(self.output_filepath)
        log_process(logger_throughput, self.capturing_process)
        self.capturing_process.start()
        self.capturing_process.wait_for_capturing_started(self.CAPTURING_STARTED_TIMEOUT)

    @with_callback_name('Stop Throughput Tshark Capturer')
    def stop(self):
        self.capturing_process.stop()


