class F1apCollector(Collector):
    CAPTURING_FILTER = 'f1ap or e1ap'

    @typed(logs_directory=Filepath())
    def __init__(self, logs_directory):
        super(F1apCollector, self).__init__()
        self.filename = unique_name('f1ap')
        self._logs_directory = logs_directory
        self._output_filepath = os.path.join(self._logs_directory, self.filename) + '.pcap'
        self._messages_collector = Tjellyfish()

    def start(self):
        command = TcpDump()
        command.set_snaplen(0).buffered_packets().dont_convert_addresses().write_to_std().set_interface('any', 'sctp')

        self._messages_collector.set_output_file(self._messages_collector.PIPE)
        self._messages_collector.set_remote_stdin(remote_ip=GNB_LMP_IP, command=command)
        self._messages_collector.start(stdout=self._output_filepath)

    @with_callback_name('Stop F1ap Collector')
    def stop(self):
        self._messages_collector.stop()
        apply_filter(self._output_filepath, self.CAPTURING_FILTER)

    def _filename_without_extension(self):
        return self.filename.rstrip('.pcap')


class L3apCollector(Collector):
    @typed(logs_directory=Filepath())
    def __init__(self, logs_directory):
        super(L3apCollector, self).__init__()
        self._logs_directory = logs_directory
        self._messages_collector = ta5g_tshark()

    def start(self):
        self._messages_collector.start_collecting_L3_on_AP_remote_interface(
            log_filename_prefix='l3ap',
            log_dirpath=self._logs_directory)

    @with_callback_name('Stop L3ap Collector')
    def stop(self):
        self._messages_collector.stop_tcpdump_on_remote_interface()
